'use strict';
// An additive JavaLingo workspace. It never changes lessons, progress, or the game.
(() => {
  const cases = [
    {title:'Variáveis · o valor mudou?', tag:'Comece aqui', concept:'Atribuição', code:'int pontos = 4;\npontos = pontos + 3;\nSystem.out.println(pontos);', output:'7', steps:['pontos começa valendo 4.','A expressão pontos + 3 usa o valor atual (4), chegando a 7.','A atribuição guarda 7 em pontos; println mostra esse valor.'], prompt:'Por que o resultado não é 4 nem 43?', tryIt:'Troque 3 por 5. Qual será a saída?', clue:'Leia o lado direito da atribuição antes de atualizar a variável.'},
    {title:'Condição · qual caminho?', tag:'Decisões', concept:'if / else', code:'int idade = 17;\nif (idade >= 18) {\n    System.out.println("Pode entrar");\n} else {\n    System.out.println("Ainda não");\n}', output:'Ainda não', steps:['idade vale 17.','17 >= 18 é falso.','O bloco else é executado; o bloco if não é.'], prompt:'O que aconteceria se idade fosse 18?', tryIt:'Mude >= para > e use idade = 18. O que mudou?', clue:'Antes de olhar os blocos, resolva a comparação como verdadeiro ou falso.'},
    {title:'Laço · quantas vezes?', tag:'Repetição', concept:'for', code:'for (int i = 0; i < 3; i++) {\n    System.out.println(i);\n}', output:'0\n1\n2', steps:['i começa em 0 e a condição 0 < 3 é verdadeira.','Imprime 0; i passa a 1. Depois imprime 1 e 2.','Quando i chega a 3, 3 < 3 é falso e o laço termina.'], prompt:'Por que não aparece o número 3?', tryIt:'Troque i < 3 por i <= 3. Qual é a nova saída?', clue:'Anote o valor de i antes de cada println.'},
    {title:'Método · de onde veio?', tag:'Métodos', concept:'Parâmetro e argumento', code:'static int dobro(int numero) {\n    return numero * 2;\n}\nSystem.out.println(dobro(6));', output:'12', steps:['A chamada dobro(6) envia 6 como argumento.','O parâmetro numero recebe 6 dentro do método.','return devolve 12 para a chamada; println imprime 12.'], prompt:'O que representa numero dentro do método?', tryIt:'Chame dobro(9). Qual valor volta?', clue:'Siga o valor 6 da chamada para dentro do método.'},
    {title:'Objeto · estado próprio', tag:'POO', concept:'Classe e objeto', code:'class Conta { int saldo = 10; }\nConta a = new Conta();\nConta b = new Conta();\na.saldo += 5;\nSystem.out.println(b.saldo);', output:'10', steps:['new Conta() cria dois objetos diferentes.','a.saldo muda de 10 para 15.','b.saldo pertence ao outro objeto e continua 10.'], prompt:'Por que mudar a não alterou b?', tryIt:'Imprima a.saldo também. Quais são os dois valores?', clue:'Pense em duas caixas separadas, cada uma com seu próprio saldo.'},
    {title:'Swing · clique e evento', tag:'Interface', concept:'Listener', code:'JButton botao = new JButton("Somar");\nint[] total = {0};\nbotao.addActionListener(e -> {\n    total[0]++;\n    System.out.println(total[0]);\n});', output:'Um clique: 1\nDois cliques: 2', steps:['O listener registra o que fazer quando o botão for clicado.','Antes dos cliques, total[0] vale 0; registrar o listener não imprime nada.','Cada clique executa o bloco, incrementa e imprime o novo valor.'], prompt:'Quando o código dentro do listener é executado?', tryIt:'O que acontece se ninguém clicar?', clue:'Separe a criação do botão do evento de clique.'}
  ];
  const state={index:0,prediction:'',question:'',ownCode:'',revealed:false,messages:[],busy:false,notice:'',recognition:null};
  let visitor;
  try { visitor=localStorage.getItem('javalingo-visitor-v1');if(!/^[0-9a-f-]{36}$/.test(visitor||'')){visitor=crypto.randomUUID();localStorage.setItem('javalingo-visitor-v1',visitor)} } catch { visitor=crypto.randomUUID(); }
  const example=()=>cases[state.index];
  const save=()=>{try{sessionStorage.setItem('javalingo-reasoning-v1',JSON.stringify({index:state.index,prediction:state.prediction,question:state.question,ownCode:state.ownCode,revealed:state.revealed,messages:state.messages.slice(-12)}))}catch{}};
  try{const stored=JSON.parse(sessionStorage.getItem('javalingo-reasoning-v1')||'{}');if(Number.isInteger(stored.index)&&cases[stored.index])state.index=stored.index;if(typeof stored.prediction==='string')state.prediction=stored.prediction.slice(0,2000);if(typeof stored.question==='string')state.question=stored.question.slice(0,2000);if(typeof stored.ownCode==='string')state.ownCode=stored.ownCode.slice(0,3000);state.revealed=stored.revealed===true;if(Array.isArray(stored.messages))state.messages=stored.messages.filter(m=>['user','assistant'].includes(m?.role)&&typeof m.text==='string').slice(-12)}catch{}
  const previousRender=render, previousNav=setNav;
  setNav=function(){previousNav();if(screen==='reasoning')$('#breadcrumb').textContent='Javailson · IA de Java'};
  render=function(){if(screen==='reasoning'){setNav();updateStats();renderReasoning();return}previousRender()};
  const messageMarkup=m=>`<article class="reason-message ${m.role==='user'?'from-student':'from-mentor'}"><strong>${m.role==='user'?'Você':'Javailson'}</strong><p>${esc(m.text)}</p></article>`;
  function renderReasoning(){const item=example();app.innerHTML=`<div class="reason-page"><header class="reason-hero"><div><span class="reason-hero-kicker"><span class="reason-kicker-dot" aria-hidden="true"></span> SEU PARCEIRO DE ESTUDOS EM JAVA</span><h1>Javailson<span class="reason-title-spark" aria-hidden="true">✦</span></h1><p>Fale ou escreva sua dúvida, teste o que você entendeu e aprenda a pensar no código, passo a passo.</p><div class="reason-hero-pills"><span>Converse com a IA</span><span>Pratique com exemplos</span><span>Fale ou digite</span></div></div><img class="reason-hero-illustration" src="assets/professor-nao-grita.webp" alt="Professor em desenho animado com a camiseta Não grita! fazendo sinal de silêncio"><img class="reason-hero-mobile-portrait" src="assets/professor-nao-grita.webp" alt="" aria-hidden="true"></header><div class="reason-layout"><div class="reason-main"><section class="reason-card"><div class="reason-section-head"><span class="reason-number">01</span><div><span class="eyebrow">ESCOLHA UMA SITUAÇÃO</span><h2>O que vai acontecer?</h2></div></div><div class="reason-case-picker" role="group" aria-label="Exemplos de Java">${cases.map((c,i)=>`<button type="button" data-reason-case="${i}" aria-pressed="${state.index===i}"><small>${esc(c.tag)}</small><strong>${esc(c.title)}</strong></button>`).join('')}</div><div class="reason-code-heading"><span>${esc(item.concept)} · Java</span><span>Leia com calma</span></div><pre class="reason-code"><code>${esc(item.code)}</code></pre><p class="reason-prompt">${esc(item.prompt)}</p></section><section class="reason-card"><div class="reason-section-head"><span class="reason-number">02</span><div><span class="eyebrow">SUAS PALAVRAS PRIMEIRO</span><h2>Qual é sua hipótese?</h2></div></div><label class="reason-label" for="reasonPrediction">Escreva o resultado esperado e por quê</label><textarea id="reasonPrediction" maxlength="2000" placeholder="Eu acho que vai mostrar... porque...">${esc(state.prediction)}</textarea><div class="reason-actions"><button type="button" class="reason-primary" data-reason-reveal>${state.revealed?'Rever explicação':'Conferir passo a passo'}</button><button type="button" class="reason-secondary" data-reason-dictate="prediction">Falar minha hipótese</button></div><p class="reason-small">A hipótese é sua: a conferência mostra a explicação deste exemplo. Para conversar sobre a sua hipótese, pergunte ao Javailson.</p><div id="reasonReveal">${state.revealed?revealMarkup(item):''}</div></section><section class="reason-card reason-challenge"><span class="eyebrow">03 · AGORA É COM VOCÊ</span><h2>Mude uma coisa e preveja de novo</h2><p>${esc(item.tryIt)}</p><button type="button" class="reason-secondary" data-reason-next>Outro exemplo →</button></section></div><aside class="reason-tutor reason-card"><div class="reason-tutor-header"><div class="reason-tutor-icon" aria-hidden="true"><img src="assets/professor-cartoon-portrait.webp" alt=""></div><div><span class="eyebrow">CONVERSE COM A IA</span><h2>Fale com o Javailson</h2></div></div><p>Travou em alguma parte? Conte como você pensou, peça uma pista ou mostre seu código. O Javailson ajuda você a encontrar o próximo passo.</p><div class="reason-quick"><button type="button" data-reason-quick="pista">Quero uma pista</button><button type="button" data-reason-quick="linha">Explique uma linha</button><button type="button" data-reason-quick="comparar">Confira minha hipótese</button></div><div class="reason-chat" id="reasonChat" role="log" aria-label="Conversa com o Javailson" aria-live="polite">${state.messages.length?state.messages.map(messageMarkup).join(''):'<div class="reason-empty"><span class="reason-empty-icon" aria-hidden="true">✦</span><strong>Vamos pensar juntos?</strong><span>Experimente: “Por que o laço não imprime 3?”</span></div>'}</div><label class="reason-label" for="reasonQuestion">Sua dúvida</label><textarea id="reasonQuestion" maxlength="2000" placeholder="Eu pensei que... Mas não entendi por que...">${esc(state.question)}</textarea><label class="reason-label" for="reasonOwnCode">Seu código Java (opcional)</label><textarea id="reasonOwnCode" maxlength="3000" spellcheck="false" placeholder="Cole aqui o trecho que você quer entender">${esc(state.ownCode)}</textarea><div class="reason-actions"><button type="button" class="reason-primary" data-reason-send ${state.busy?'disabled':''}>${state.busy?'Pensando…':'Perguntar ao Javailson'}</button><button type="button" class="reason-secondary" data-reason-dictate="question">Falar</button></div><p class="reason-status" id="reasonStatus" role="status">${esc(state.notice)}</p><p class="reason-small">A fala vira texto para você revisar antes de enviar. Ao enviar, sua pergunta, sua hipótese, seu código e o exemplo vão para a IA do Google. Use até 20 perguntas por navegador por dia; a cota é compartilhada entre todos os alunos. Não inclua dados pessoais. O ditado depende do navegador. Respostas da IA podem falhar; confira o código executando-o na Prática de código.</p></aside></div></div>`;const chat=app.querySelector('#reasonChat');if(chat)chat.scrollTop=chat.scrollHeight}
  function revealMarkup(c){return `<div class="reason-reveal"><div><span class="eyebrow">SAÍDA ESPERADA DO EXEMPLO</span><pre>${esc(c.output)}</pre></div><div><span class="eyebrow">SIGA O VALOR</span><ol>${c.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><strong>Pista para pensar:</strong> ${esc(c.clue)}</p></div></div>`}
  function updateChat(){const chat=app.querySelector('#reasonChat');if(chat){chat.innerHTML=state.messages.map(messageMarkup).join('');chat.scrollTop=chat.scrollHeight}const status=app.querySelector('#reasonStatus');if(status)status.textContent=state.notice;const send=app.querySelector('[data-reason-send]');if(send){send.disabled=state.busy;send.textContent=state.busy?'Pensando…':'Perguntar ao Javailson'}}
  function readDrafts(){state.prediction=app.querySelector('#reasonPrediction')?.value.slice(0,2000)??state.prediction;state.question=app.querySelector('#reasonQuestion')?.value.slice(0,2000)??state.question;state.ownCode=app.querySelector('#reasonOwnCode')?.value.slice(0,3000)??state.ownCode;save()}
  async function send(){readDrafts();const question=state.question.trim();if(!question){state.notice='Escreva ou dite uma pergunta antes de enviar.';updateChat();return}if(state.busy)return;state.busy=true;state.notice='Enviando sua pergunta…';const history=state.messages.slice(-6).map(m=>({role:m.role,text:m.text}));state.messages.push({role:'user',text:question});state.question='';const field=app.querySelector('#reasonQuestion');if(field)field.value='';updateChat();save();try{const res=await fetch('/api/reasoning/chat',{method:'POST',headers:{'content-type':'application/json','x-jl-visitor':visitor},body:JSON.stringify({code:example().code,context:example().title,prediction:state.prediction,ownCode:state.ownCode,question,history})});const data=await res.json();if(!res.ok)throw Error(data.error||'Não foi possível conversar agora.');state.messages.push({role:'assistant',text:data.reply});state.notice='';}catch(e){state.messages.pop();state.question=question;if(field)field.value=question;state.notice=e.message||'Não foi possível conversar agora.';}finally{state.busy=false;save();if(screen==='reasoning')updateChat()}}
  function dictate(target){readDrafts();const input=app.querySelector(target==='prediction'?'#reasonPrediction':'#reasonQuestion');if(!input)return;if(state.recognition){state.recognition.stop();return}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){state.notice='O ditado não está disponível neste navegador. Digite sua explicação.';updateChat();return}const recognition=new Recognition();recognition.lang='pt-BR';recognition.interimResults=false;recognition.continuous=false;state.recognition=recognition;state.notice='Ouvindo… fale sua explicação. Toque novamente para parar.';updateChat();recognition.onresult=e=>{const words=Array.from(e.results).map(r=>r[0]?.transcript||'').join(' ').trim();input.value=(input.value.trim()+' '+words).trim().slice(0,2000);readDrafts();state.notice='Transcrição pronta. Revise o texto antes de enviar.';updateChat()};recognition.onerror=e=>{state.notice=e.error==='not-allowed'?'Permita o microfone no navegador para ditar.':'Não foi possível transcrever. Você pode digitar sua explicação.';updateChat()};recognition.onend=()=>{state.recognition=null;if(state.notice.startsWith('Ouvindo')){state.notice='Ditado encerrado. Confira o texto ou tente novamente.';updateChat()}};try{recognition.start()}catch{state.recognition=null;state.notice='O ditado não está disponível neste navegador.';updateChat()}}
  function stopVoice(){if(state.recognition)state.recognition.stop()}
  app.addEventListener('input',e=>{if(e.target.matches('#reasonPrediction,#reasonQuestion,#reasonOwnCode'))readDrafts()});
  app.addEventListener('click',e=>{const b=e.target.closest('[data-reason-case],[data-reason-reveal],[data-reason-next],[data-reason-quick],[data-reason-send],[data-reason-dictate]');if(!b)return;if(b.dataset.reasonCase!==undefined){readDrafts();stopVoice();state.index=Number(b.dataset.reasonCase);state.prediction='';state.question='';state.ownCode='';state.revealed=false;state.messages=[];state.notice='';save();renderReasoning()}else if(b.hasAttribute('data-reason-reveal')){readDrafts();state.revealed=true;app.querySelector('#reasonReveal').innerHTML=revealMarkup(example());save()}else if(b.hasAttribute('data-reason-next')){readDrafts();state.index=(state.index+1)%cases.length;state.prediction='';state.question='';state.ownCode='';state.revealed=false;state.messages=[];state.notice='';save();renderReasoning();app.querySelector('.reason-card')?.scrollIntoView({behavior:'smooth'})}else if(b.dataset.reasonQuick){readDrafts();const drafts={pista:'Me dê uma pista sem entregar a resposta. Ajude-me a pensar.',linha:'Explique a linha mais importante deste exemplo com palavras simples.',comparar:'Compare minha hipótese com o código. Diga o que entendi e o que preciso revisar, com uma pergunta para eu responder.'};const input=app.querySelector('#reasonQuestion');input.value=drafts[b.dataset.reasonQuick];readDrafts();input.focus()}else if(b.hasAttribute('data-reason-send'))send();else if(b.dataset.reasonDictate)dictate(b.dataset.reasonDictate)});
})();
